-- Benefit periods: the four default quarters become the prototype's quarters, shifted with
-- every other date (an update rather than delete + insert, so nothing is destroyed).

update public.benefit_periods bp set id = v.id, label = v.label, start_date = v.start_date, finish_date = v.finish_date
from (select p.id as old_id, row_number() over (order by p.start_date) as n from public.benefit_periods p where p.organisation_id = '98e086a1-6b01-521a-92e9-21dac759c8f4') x
join (values
  (1, u('451bd3f42c75'), 'Q1 Aug–Oct 2026', d(-51), d(40)),
  (2, u('20a4f44e1840'), 'Q2 Nov 2026–Jan 2027', d(41), d(132)),
  (3, u('d63dcab62ed2'), 'Q3 Feb–Apr 2027', d(133), d(221)),
  (4, u('c16773705b96'), 'Q4 May–Jul 2027', d(222), d(313))
) v(n, id, label, start_date, finish_date) on v.n = x.n
where bp.id = x.old_id;





