insert into public.strategic_objectives (id, portfolio_id, title, description, owner_id) values
  (u('8bde87cdf5d3'), u('ffeb12c2b6d8'), 'Outstanding student experience', 'Create inclusive, reliable and responsive digital services for every student.', u('44c529d01644')),
  (u('9b1fa1ac22e0'), u('ffeb12c2b6d8'), 'Research excellence and capability', 'Provide secure, scalable digital capability for world-class research.', u('2ab4697c4e71')),
  (u('948f8b2e6c03'), u('ffeb12c2b6d8'), 'Financial sustainability', 'Deliver demonstrable value and reduce avoidable technology costs.', u('b3c221e80091')),
