insert into public.programmes (id, portfolio_id, name, description, manager_id, project_manager_id, project_officer_id, sponsor_id, start_date, finish_date, budget, value_statement) values
  (u('b21d00504ff9'), u('ffeb12c2b6d8'), '1. Standards, Governance & Best Practice', 'Strengthening governance, assurance and consistent delivery standards across DTS.', u('19431d6d38d2'), u('403b3213de11'), u('ab8e89a367f7'), u('2ab4697c4e71'), d(-416), d(313), 1450000, 'Create trusted, repeatable ways of working that improve delivery confidence and decision quality.'),
  (u('9da2a1c26250'), u('ffeb12c2b6d8'), '2. Resilience & Business Continuity', 'Improving cyber security, infrastructure resilience and continuity of critical services.', u('d92642368f2e'), u('11deba8aff2d'), u('e905f9d330cc'), u('4938bab356ec'), d(-385), d(466), 2380000, 'Protect teaching, research and operations from disruption while reducing institutional risk.'),
  (u('7299a996d3df'), u('ffeb12c2b6d8'), '3. Optimisation & Cost Management', 'Modernising core services and improving the value delivered by technology investments.', u('8e958cedaf06'), u('11deba8aff2d'), u('7400edd42d7b'), u('b3c221e80091'), d(-355), d(313), 1720000, 'Release capacity and reduce avoidable cost through a simpler, better-managed technology estate.'),
  (u('0ae203dc50c2'), u('ffeb12c2b6d8'), '4. Efficiency, Automation & AI', 'Using automation and responsible AI to create better staff and student experiences.', u('ba49f3b117ef'), u('403b3213de11'), u('ab8e89a367f7'), u('44c529d01644'), d(-416), d(466), 1910000, 'Give colleagues time back and improve service quality through practical, responsible automation.'),
  (u('c687f14f1122'), u('ffeb12c2b6d8'), '5. People, Knowledge & Continuous Improvement', 'Building digital capability, knowledge and a culture of continuous improvement.', u('14bc1fde8bed'), u('403b3213de11'), u('e905f9d330cc'), u('c9ac15caa52b'), d(-263), d(313), 1290000, 'Equip teams with the skills, insight and confidence to sustain digital improvement.');
