  (u('83fd185ac40e'), u('142484a15181'), null, null, 'Approve move of Ebbot to Phase 4 subject to TOPdesk catalogue clean-up', 'The assistant is ready to build, but routing depends on a service catalogue that still contains duplicated and unowned entries. Moving to Phase 4 without the clean-up risks rework during testing.', 'Conditional approval keeps the pilot date while making the catalogue clean-up an explicit, owned dependency with a board-visible date.', u('19431d6d38d2'), lk('decision_forum', 'Project Board'), d(-10), d(-11), 'made', false, 'No change to agreed scope.', false, 'Absorbed within the approved budget.', true, 'Phase 4 entry is conditional on 13/11/2026.', true, 'Protects the reduced service desk contacts profile from Q3.', 'Ebbot Project Board minutes 10-09-2026.docx'),
  (u('a107986aaaed'), u('9da5bf399c5c'), null, null, 'Descope Implement New Service Point', 'The walk-up service point was scoped before the assistant pilot. Footfall has fallen 38% year on year and the space is now required by Estates.', 'Falling footfall and the unavailability of the space mean the original benefit cannot be realised; the funding does more good against the assistant''s knowledge base.', u('b3c221e80091'), lk('decision_forum', 'Programme Board'), d(-24), d(-25), 'made', true, 'Service point removed from scope.', true, '£46k released back to the programme.', false, 'No change to the closure date.', true, 'Original footfall benefit withdrawn; knowledge benefit strengthened.', 'Optimisation Programme Board minutes 27-08-2026.docx'),
  (u('a47b8c51b82c'), u('eead769f0dd2'), null, null, 'Choose storage expansion option', 'Research storage will reach 92% capacity by February 2027. Three options were appraised against cost, resilience and the net zero objective.', null, u('d92642368f2e'), lk('decision_forum', 'Architecture Review Board'), d(18), null, 'pending', true, 'Determines the migration scope for DFS work.', true, 'Whole-life cost varies by £180k across the options.', true, 'Option 3 adds three months.', true, 'Only options 2 and 3 support the energy reduction benefit.', null),
  (u('24de31ceff03'), u('3d826f127772'), null, null, 'Hold the VDI pilot until the data centre network is stable', 'The giving milestone for the network refresh has slipped to 20 November, past the VDI required-by date of 30 October. Starting the pilot on an unstable network would invalidate the performance testing.', null, u('8e958cedaf06'), lk('decision_forum', 'Project Board'), d(-3), null, 'pending', false, 'No scope change.', false, 'No additional cost.', true, 'Pilot start moves from 30/10/2026 to at least 04/12/2026.', true, 'Device experience benefit slips one quarter.', null),
  (u('897d255dba3a'), u('4f04ca0606e5'), null, null, 'Agree the Copilot licensing model for 2026/27', 'Departmental demand exceeds the pilot allocation. Central funding, devolved purchase and a hybrid allocation model were compared.', null, u('b3c221e80091'), lk('decision_forum', 'Digital Committee'), d(-10), null, 'pending', true, 'Determines the rollout population.', true, 'Between £96k and £310k per year.', false, 'No change to the delivery plan.', true, 'Adoption level drives the time-back benefit.', null),
  (u('0dd097bd6280'), u('4d36d64eb0e3'), null, null, 'Confirm the CIS safeguard implementation order', 'Implementation Group 1 safeguards can be sequenced by insurer priority or by internal risk score. The two orders differ for six safeguards.', 'The merged order meets the insurer evidence deadline without leaving the two highest internal risks unaddressed into the new year.', u('4938bab356ec'), lk('decision_forum', 'Programme Board'), d(-17), d(-18), 'made', false, 'No change to the safeguard set.', false, 'No change to cost.', true, 'Adds two weeks to the overall sequence.', true, 'Protects the cyber insurance compliance benefit.', 'Resilience Programme Board minutes 03-09-2026.docx'),
  (u('e9b748646481'), u('7bf981df49da'), null, null, 'Accept the revised vendor delivery date for core switching', 'Dataflow Systems has confirmed a four week slip on core switch delivery. Accepting it moves the Network stable milestone to 20 November.', 'The premium for alternative hardware is not justified; the slip is manageable if the two dependent projects are told now and the VDI pilot is rescheduled.', u('d92642368f2e'), lk('decision_forum', 'Project Board'), d(-5), d(-5), 'made', false, 'No scope change.', false, 'Contract price unchanged.', true, 'Network stable moves from 16/10/2026 to 20/11/2026.', true, 'Downtime reduction benefit starts one quarter later.', 'Network Refresh Project Board minutes 16-09-2026.docx'),
  (u('435fef8667d0'), u('224158ac65c8'), null, null, 'Choose the SITS integration pattern for admissions automation', 'Automation can integrate through the supported REST interface or through direct database views. The review board must set the pattern before build starts.', null, u('3260734c20c8'), lk('decision_forum', 'Architecture Review Board'), d(-5), null, 'pending', true, 'Determines which admissions steps can be automated.', true, 'Option 2 adds ongoing maintenance cost.', true, 'Option 1 adds four weeks of build.', true, 'Field coverage limits the automation benefit.', null),
  (u('c00fb878148b'), u('e873e6f6c192'), null, null, 'Select the asset management tooling', 'The asset baseline can be held in the existing service management platform or a dedicated discovery tool.', 'Manual reconciliation was the root cause of the previous asset baseline going stale within six months; automated discovery is the only option that sustains the benefit.', u('8e958cedaf06'), lk('decision_forum', 'Architecture Review Board'), d(-31), d(-32), 'made', true, 'Adds an integration to the scope.', true, '£38k recurring.', true, 'Adds three weeks.', true, 'Protects the asset accuracy benefit beyond closure.', 'Architecture Review Board minutes 20-08-2026.docx'),
  (u('ea3afce0c9ce'), u('13f8340e52de'), null, null, 'Approve a change freeze exemption for the December deployment wave', 'Wave 4 falls inside the winter change freeze. Deferring it pushes 900 devices into the exam period.', null, u('a1cee910a6d1'), lk('decision_forum', 'Change Advisory Board'), d(67), null, 'pending', false, 'No scope change.', true, 'Deferral extends support costs by £14k.', true, 'Determines whether wave 4 lands in December or January.', false, 'No change to the benefit profile.', null),
  (u('15e655fe6554'), null, u('0ae203dc50c2'), null, 'Agree the attribution rule for shared service desk benefits', 'Reduced service desk contacts is claimed by both the assistant and the service desk optimisation project. Double counting would overstate portfolio value by £96k.', 'A documented attribution rule prevents recurrence and brings the portfolio total back to a defensible figure.', u('6044146c5e48'), lk('decision_forum', 'Programme Board'), d(-38), d(-39), 'made', false, 'No delivery scope change.', false, 'No cost change.', false, 'No schedule change.', true, 'Reduces claimed portfolio benefit by £96k.', 'Benefits attribution paper 13-08-2026.pdf'),
  (u('3a39468f769d'), u('8a7cb8a34a3f'), null, null, 'Set the assurance level for research triage models', 'Models that classify research data need an assurance level agreeing before they can run unsupervised.', null, u('2ab4697c4e71'), lk('decision_forum', 'Digital Committee'), d(25), null, 'pending', true, 'Determines the review workflow.', false, 'No cost change.', false, 'No schedule change.', true, 'Directly sets the triage time saving and the assurance disbenefit.', null),
  (u('8ef4dafde6f6'), null, u('b21d00504ff9'), null, 'Standardise on Planner Premium for medium and large projects', 'Three task tools are in use across the portfolio, which prevents a single view of effort and progress.', 'The reporting overhead of three tools already exceeds the migration effort, and the licences are sunk cost.', u('6044146c5e48'), lk('decision_forum', 'Programme Board'), d(-59), d(-60), 'superseded', false, 'No project scope change.', false, 'Licences already held.', true, 'Two weeks of migration per project.', false, 'No benefit impact.', 'Standards Programme Board minutes 23-07-2026.docx'),
  (u('5f2acc9075de'), null, u('b21d00504ff9'), null, 'Standardise on Planner Premium for all projects with more than 20 tasks', 'The tier-based rule left several task-heavy small projects reporting manually. The board asked for a size-based rule instead.', 'Tier is a proxy for governance, not for reporting load; a task-count rule captures the projects that actually affect the portfolio view.', u('6044146c5e48'), lk('decision_forum', 'Programme Board'), d(-17), d(-18), 'made', false, 'No project scope change.', false, 'No cost change.', true, 'Adds four small projects to the migration list.', false, 'No benefit impact.', 'Standards Programme Board minutes 03-09-2026.docx'),
  (u('ee5285342969'), u('92aa5819c4ed'), null, null, 'Confirm whether the recovery service covers student identities in phase one', 'Phase one was scoped for staff identities. Including students triples the directory size and needs a second recovery environment.', null, u('4938bab356ec'), lk('decision_forum', 'Digital Committee'), d(60), null, 'pending', true, 'Determines the phase one population.', true, 'Up to £120k.', true, 'Up to four months.', true, 'Changes the recovery time benefit profile.', null),
  (u('63807100341a'), u('34363923f41b'), null, null, 'Approve the file share retention schedule', 'The proposed schedule deletes unaccessed files after seven years. Two faculties have asked for an exemption.', null, u('2ab4697c4e71'), lk('decision_forum', 'Digital Committee'), d(116), null, 'pending', true, 'Sets which shares are in scope.', true, 'Exemptions reduce the storage saving by an estimated £18k.', false, 'No schedule change.', true, 'Reduces the storage cost benefit.', null);
insert into public.decision_options (id, decision_id, title, pros, cons, sort_order) values
  (u('1c2229121eb7'), u('83fd185ac40e'), 'Approve Phase 4 now, clean the catalogue in parallel', array['Keeps the January pilot date', 'Build team stays engaged'], array['Routing rules may need rework', 'Testing could surface catalogue defects late'], 1),
  (u('9601fd087bfe'), u('83fd185ac40e'), 'Approve Phase 4 conditional on catalogue clean-up completing by 13 November', array['Protects the pilot date', 'Gives the service desk a firm deadline'], array['Conditional approvals need tracking', 'Slips if the clean-up slips'], 2),
  (u('f45fa2ad83dd'), u('83fd185ac40e'), 'Hold at Phase 3 until the catalogue is clean', array['Lowest rework risk'], array['Pilot slips by at least a term', 'Team released to other work'], 3),
  (u('630869d4b0cb'), u('a107986aaaed'), 'Deliver the service point as scoped', array['Honours the original business case', 'Visible presence on campus'], array['Low forecast usage', 'Ongoing staffing cost', 'Estates space is not available until 2028'], 1),
  (u('b87d20d60be5'), u('a107986aaaed'), 'Descope and redirect the funding to assistant knowledge curation', array['Releases £46k', 'Strengthens a benefit already in realisation'], array['Perception of reduced physical presence', 'Needs a communications plan'], 2),
  (u('f4b4a390b33f'), u('a47b8c51b82c'), 'Extend the existing on-premises array', array['Lowest capital cost', 'No migration needed'], array['Array is end of support in 2029', 'No improvement in resilience'], 1),
  (u('475bf7a45fcc'), u('a47b8c51b82c'), 'Hybrid tier with cloud archive for cold data', array['Balances cost and resilience', 'Reduces data hall power draw'], array['Needs a data classification exercise', 'Egress costs to model'], 2),
  (u('eddf13dd58f8'), u('a47b8c51b82c'), 'Full cloud migration', array['Highest resilience', 'No hardware refresh'], array['Highest whole-life cost', 'Research workloads are latency sensitive'], 3),
  (u('0a23e2747b90'), u('24de31ceff03'), 'Start the pilot on the current network', array['Keeps the published date'], array['Performance results would not be credible', 'Likely rerun of testing'], 1),
  (u('8d584664f65a'), u('24de31ceff03'), 'Hold the pilot until the network is signed off stable', array['Credible test results', 'Protects the business case'], array['Six week delay to the pilot', 'Pilot cohort needs re-engaging'], 2),
  (u('b70320989ab2'), u('897d255dba3a'), 'Central funding for all staff', array['Simple to administer', 'Equitable access'], array['£310k annual cost', 'Low predicted utilisation in some areas'], 1),
  (u('f804966a1861'), u('897d255dba3a'), 'Devolved purchase by faculty', array['Cost follows demand'], array['Fragmented governance', 'No institutional view of value'], 2),
  (u('e74f3b35b7e8'), u('897d255dba3a'), 'Hybrid: central core allocation plus devolved top-up', array['Predictable base cost', 'Demand-led growth'], array['Needs an allocation rule', 'Annual review overhead'], 3),
  (u('9fc2d6ecd4a6'), u('0dd097bd6280'), 'Follow the insurer priority order', array['Fastest route to the insurance requirement'], array['Leaves two high internal risks open longer'], 1),
  (u('5cb91cb54551'), u('0dd097bd6280'), 'Follow the internal risk score', array['Addresses the biggest exposure first'], array['Insurance evidence deadline is at risk'], 2),
  (u('2d53c2cd6683'), u('0dd097bd6280'), 'Merge both, insurer-critical first then risk score', array['Meets the deadline and the risk appetite'], array['Slightly longer overall programme'], 3),
  (u('e9a120de99d8'), u('e9b748646481'), 'Accept the revised date', array['No change of supplier', 'Contract pricing retained'], array['Network stable milestone slips past two dependent projects'' required-by dates'], 1),
  (u('4c78fcad4714'), u('e9b748646481'), 'Source alternative hardware from a second supplier', array['Recovers the original date'], array['23% price premium', 'Different support model'], 2),
  (u('7ac47254984b'), u('435fef8667d0'), 'Supported REST interface', array['Vendor supported', 'Survives upgrades'], array['Rate limits need managing', 'Some fields unavailable'], 1),
  (u('05df80ee2df4'), u('435fef8667d0'), 'Direct database views', array['Full field coverage', 'No rate limits'], array['Breaks on upgrade', 'Outside vendor support'], 2),
  (u('d003b206c0b8'), u('c00fb878148b'), 'Extend the existing service management platform', array['No new supplier', 'Single source for CIs'], array['Weaker discovery', 'Manual reconciliation'], 1),
  (u('412e4599024f'), u('c00fb878148b'), 'Dedicated discovery tooling with a feed into service management', array['Accurate automated discovery'], array['£38k per year', 'Integration to build and support'], 2),
  (u('dc66f31791b3'), u('ea3afce0c9ce'), 'Defer wave 4 to January', array['Respects the freeze'], array['900 devices deploy during exams', 'Extended support cost continues'], 1),
  (u('9733b4c603ca'), u('ea3afce0c9ce'), 'Seek a freeze exemption for low-risk faculty devices only', array['Avoids exam-period disruption', 'Scoped risk'], array['Exemption sets a precedent', 'Needs CAB approval'], 2),
  (u('9ceb614645e2'), u('15e655fe6554'), 'Attribute wholly to the assistant', array['Simple'], array['Ignores process change contribution'], 1),
  (u('9f970d61e8c1'), u('15e655fe6554'), 'Split 70/40 as currently recorded', array['Reflects both contributions'], array['Totals 110% and overstates value'], 2),
  (u('7a657a1886a9'), u('15e655fe6554'), 'Split 60/40 and record the rule in the benefits framework', array['Adds to 100%', 'Repeatable for future shared benefits'], array['Requires both profiles to be reissued'], 3),
  (u('bb54182117c6'), u('3a39468f769d'), 'Human in the loop for all classifications', array['Lowest risk'], array['Removes most of the time saving'], 1),
  (u('5795fc569c0f'), u('3a39468f769d'), 'Human review of low-confidence classifications only', array['Retains most of the benefit', 'Focuses effort where it matters'], array['Needs a confidence threshold and monitoring'], 2),
  (u('3cb91bc5f5fb'), u('3a39468f769d'), 'Fully automated with quarterly audit', array['Maximum time saving'], array['Unacceptable to the research ethics panel'], 3),
  (u('02ebb2aa2c61'), u('8ef4dafde6f6'), 'Mandate Planner Premium for medium and large projects', array['Single reporting view', 'Licences already held'], array['Migration effort for eight projects'], 1),
  (u('79b4bda8129b'), u('8ef4dafde6f6'), 'Allow any tool with a reporting export', array['No migration'], array['Reporting stays manual', 'No effort roll-up'], 2),
  (u('c8a0ddee02f5'), u('5f2acc9075de'), 'Keep the tier-based rule', array['Already communicated'], array['Task-heavy small projects stay outside reporting'], 1),
  (u('a19fd4f0cea7'), u('5f2acc9075de'), 'Switch to a task-count rule of 20 or more tasks', array['Captures every project that materially affects reporting'], array['Requires a second round of communications'], 2),
  (u('71a698e1b84e'), u('ee5285342969'), 'Staff only in phase one', array['Deliverable within the approved budget'], array['Student services remain exposed until phase two'], 1),
  (u('9d736cb3cf60'), u('ee5285342969'), 'Staff and students in phase one', array['Removes the exposure in one step'], array['£120k additional cost', 'Adds four months'], 2),
  (u('33f136539183'), u('63807100341a'), 'Apply the schedule with no exemptions', array['Maximum storage reduction', 'Single rule to operate'], array['Faculty objection', 'Possible research data loss'], 1),
  (u('a3d6278b5a88'), u('63807100341a'), 'Apply the schedule with a documented research exemption route', array['Protects research data', 'Keeps most of the reduction'], array['Exemption register to maintain'], 2);
