insert into public.lessons (id, project_id, phase_id, sprint_name, type, category_id, summary, what_happened, impact, root_cause, recommendation, applicability, raised_by_id, raised_date, status) values
  (u('affa664dbee5'), u('142484a15181'), ph(4), null, 'problem', lk('lesson_category', 'Testing'), 'Test team availability was not agreed in advance', 'Testing was planned assuming two service desk analysts would be available; both were pulled onto incident cover in the first test week.', 'User acceptance testing started nine days late and compressed the defect fixing window.', 'Test resource was assumed rather than booked, and the service desk had no visibility of the dates.', 'Book named testers with their line manager at the point the test plan is written, and record the booking as a resource assignment.', 'all_projects', u('36e519195168'), d(-263), 'action_agreed'),
  (u('b0496867e0f1'), u('13f8340e52de'), ph(4), null, 'problem', lk('lesson_category', 'Testing'), 'Faculty testers were not released for the pilot wave', 'Faculty testers had agreed in principle at initiation but no dates were held, and three of five did not attend the test sessions.', 'Two application compatibility defects reached the first deployment wave.', 'Agreement in principle was treated as a commitment; no calendar bookings were made.', 'Convert in-principle testing agreements into diarised commitments before the gate to build.', 'similar_projects', u('11deba8aff2d'), d(-105), 'action_agreed'),
  (u('4d382faaa5ee'), u('bb3bc1733894'), ph(4), null, 'problem', lk('lesson_category', 'Testing'), 'Admissions testers were unavailable during the clearing period', 'The test window overlapped with clearing and the admissions team could not release anyone for three weeks.', 'Regression testing was cut short and two defects were found in live service.', 'The test plan was built from the delivery plan without checking the business calendar.', 'Check the business calendar for peak periods before setting test dates.', 'all_projects', u('3260734c20c8'), d(55), 'embedded'),
  (u('641fee1b5f96'), u('59cfeef95b28'), ph(4), null, 'problem', lk('lesson_category', 'Testing'), 'No named test lead until the week testing started', 'The test lead role was left unfilled while the team focused on migration planning.', 'Test scripts were written during the test window, adding two weeks.', 'The role was on the resource plan as a generic resource and never staffed.', 'Treat an unstaffed generic test role as a staffing warning that must clear before the build gate.', 'all_projects', u('157d1593d385'), d(-152), 'identified'),
  (u('d0df498fb8ef'), u('142484a15181'), ph(1), null, 'problem', lk('lesson_category', 'People & Roles'), 'No technical service owner at project start', 'The project mobilised without a named technical service owner, so design decisions had no operational sign-off.', 'Three design decisions were revisited at the design authority, costing four weeks.', 'The service owner role is not part of the mobilisation checklist.', 'Require a named technical service owner before the idea gate is passed.', 'all_projects', u('a1cee910a6d1'), d(-384), 'embedded'),
  (u('0fa7a778f9bc'), u('13f8340e52de'), ph(2), null, 'problem', lk('lesson_category', 'People & Roles'), 'Service ownership for the device estate was unclear', 'Two teams each believed the other owned the device build, and neither attended the early design sessions.', 'The image standard was agreed twice and then reworked.', 'Service ownership was never formally recorded after the last reorganisation.', 'Confirm the named service owner in writing at initiation and record them on the project record.', 'all_projects', u('d3806fe3b1be'), d(-589), 'action_agreed'),
  (u('ac641718ed43'), u('1fce5e8639fe'), ph(1), null, 'problem', lk('lesson_category', 'People & Roles'), 'No operational owner for the app after go-live', 'The app was delivered without agreeing who would manage user accounts and respond to alerts.', 'Handover slipped by six weeks while ownership was negotiated.', 'The project was small enough to skip the full initiation checklist.', 'Apply the service owner requirement to small projects as well as medium and large.', 'all_projects', u('403b3213de11'), d(-432), 'action_agreed'),
  (u('cb95d29e0cbd'), u('59cfeef95b28'), ph(1), null, 'problem', lk('lesson_category', 'People & Roles'), 'Site contacts were not identified before migration planning', 'Migration waves were planned without a named contact at each site.', 'Four sites were rescheduled after the plan was published.', 'Site contacts were assumed to be the same as phase one.', 'Refresh the stakeholder map at the start of every subsequent phase rather than inheriting it.', 'similar_projects', u('2967ce33d27c'), d(-272), 'identified'),
  (u('740e00c19406'), u('5a80b922508f'), ph(3), null, 'problem', lk('lesson_category', 'Procurement'), 'Purchase order approval delays held up tooling', 'The purchase order for the control monitoring tooling took five weeks to approve against a two week assumption.', 'The implementation start slipped by a month and the insurer evidence date became at risk.', 'The approval route for spend above £50k was not understood at planning time.', 'Include the finance approval route and realistic lead time in the delivery plan before baselining.', 'all_projects', u('161d6b100d82'), d(-141), 'embedded'),
  (u('0da1e5fbc15e'), u('bb3bc1733894'), ph(3), null, 'problem', lk('lesson_category', 'Procurement'), 'Supplier could not be engaged until the order was raised', 'The implementation partner would not commit resource until a signed order was in place, which took seven weeks.', 'Mobilisation slipped a month and the partner''s preferred team was reallocated.', 'Procurement was started after the business case was approved rather than in parallel.', 'Start the procurement route in parallel with business case approval for supplier-delivered projects.', 'similar_projects', u('eab4a1e27162'), d(19), 'action_agreed'),
  (u('276452ad6f64'), u('59cfeef95b28'), ph(3), null, 'problem', lk('lesson_category', 'Procurement'), 'Hardware order raised against the wrong cost centre', 'The order was rejected twice for coding errors before being approved.', 'Three weeks lost and the delivery slot was missed.', 'The project had no finance business partner engaged at planning.', 'Name a finance business partner in the project team for any project with capital spend.', 'all_projects', u('60da6bab9ad0'), d(-188), 'identified'),
  (u('b20239e8574b'), u('13f8340e52de'), ph(4), null, 'problem', lk('lesson_category', 'Change Management & Adoption'), 'Change and comms were engaged too late', 'The change manager was brought in two weeks before the first deployment wave.', 'Faculty communications went out late and the service desk took 340 avoidable contacts in the first week.', 'Change and communications were treated as a deployment activity rather than a delivery workstream.', 'Engage change and communications at the design gate and include them in the project team from that point.', 'all_projects', u('53c863c1f96a'), d(-28), 'embedded'),
  (u('0121e4c77c89'), u('142484a15181'), ph(3), null, 'problem', lk('lesson_category', 'Change Management & Adoption'), 'Adoption planning started after the build was underway', 'Adoption materials were commissioned once the build was well progressed, leaving no time to test messaging with students.', 'The pilot launched without a student-facing explainer, which reduced early usage.', 'The plan had no adoption activity before Phase 4.', 'Add an adoption plan to the design gate checklist.', 'similar_projects', u('36e519195168'), d(-260), 'action_agreed'),
  (u('c8777d699f8b'), u('bb3bc1733894'), ph(5), null, 'problem', lk('lesson_category', 'Change Management & Adoption'), 'Training was delivered before the final configuration was agreed', 'Training ran three weeks before go-live but the workflow configuration changed afterwards.', 'Users were trained on screens that did not match live, generating 90 service desk contacts.', 'Training dates were fixed early and not revisited when configuration slipped.', 'Re-confirm training dates against the configuration freeze date, not the go-live date.', 'similar_projects', u('11deba8aff2d'), d(-102), 'identified'),
  (u('78317be5ef31'), u('1fce5e8639fe'), ph(5), null, 'problem', lk('lesson_category', 'Change Management & Adoption'), 'Student communications missed the start of term', 'The launch communication was scheduled for the second week of term, after the safety briefings had already happened.', 'First-term registrations were 40% below forecast.', 'The comms plan was built around the project plan, not the academic calendar.', 'Align adoption activity to the academic calendar for anything student facing.', 'all_projects', u('3260734c20c8'), d(58), 'identified'),
  (u('e4c4ce4ef8ba'), u('142484a15181'), ph(4), null, 'problem', lk('lesson_category', 'Requirements'), 'Requirements emerged during testing', 'Testers raised eleven new requirements for query handling that had not surfaced in discovery.', 'Scope grew by 15% during the test phase and the pilot date moved.', 'Discovery involved service managers but not front-line analysts who handle the queries.', 'Include front-line practitioners, not only managers, in requirements workshops.', 'all_projects', u('157d1593d385'), d(-149), 'action_agreed'),
  (u('653e48f8a64b'), u('bb3bc1733894'), ph(4), null, 'problem', lk('lesson_category', 'Requirements'), 'Reporting requirements surfaced in user acceptance testing', 'Admissions raised 23 reporting requirements during acceptance testing that were not in the specification.', 'A further six weeks of build was needed after acceptance testing.', 'Reporting was treated as a phase two activity and never specified.', 'Specify reporting requirements alongside functional requirements, or explicitly defer them in writing.', 'all_projects', u('a1cee910a6d1'), d(-16), 'embedded'),
  (u('5c2db967a457'), u('13f8340e52de'), ph(4), null, 'problem', lk('lesson_category', 'Requirements'), 'Accessibility requirements were raised late by the disability service', 'Accessibility configuration requirements arrived during pilot testing.', 'The image had to be rebuilt and the first wave slipped by two weeks.', 'The disability service was not on the stakeholder map.', 'Add the disability service to the standard stakeholder map for any end user change.', 'all_projects', u('d3806fe3b1be'), d(-221), 'action_agreed'),
  (u('00670185c4d3'), u('59cfeef95b28'), ph(4), null, 'problem', lk('lesson_category', 'Requirements'), 'Emergency call routing requirements were discovered in testing', 'Statutory requirements for emergency call handling from each site were identified during test.', 'Two sites were removed from the first migration wave.', 'Phase one requirements were reused without checking site-specific statutory duties.', 'Validate inherited requirements against each new site rather than assuming reuse.', 'similar_projects', u('403b3213de11'), d(-64), 'identified'),
  (u('e36c657965be'), u('142484a15181'), ph(3), null, 'problem', lk('lesson_category', 'Project Management'), 'Project plans in Planner were not kept up to date by assignees', 'Task progress was updated by the project manager from verbal updates rather than by the assignees themselves.', 'Reported progress was consistently optimistic and two slipping tasks were spotted a fortnight late.', 'Assignees had no routine for updating and no reminder in their week.', 'Automate a weekly update reminder to assignees and report on update currency at the project board.', 'all_projects', u('2967ce33d27c'), d(96), 'action_agreed'),
  (u('2c5ffbccf9a5'), u('5a80b922508f'), ph(3), null, 'problem', lk('lesson_category', 'Project Management'), 'Task updates stopped once the plan moved to Planner', 'The plan was migrated mid-project and the team continued to use the old spreadsheet.', 'For three weeks the portfolio view showed no progress on a red project.', 'The migration had no cut-over communication or training.', 'When moving a plan between tools, run a short handover session and remove the old tool.', 'all_projects', u('161d6b100d82'), d(-138), 'identified'),
  (u('b515b6bc3d1c'), u('13f8340e52de'), ph(5), null, 'problem', lk('lesson_category', 'Project Management'), 'Deployment wave tasks were closed in bulk after the event', 'Wave tasks were marked complete weeks after deployment, in a single bulk update.', 'Effort actuals were meaningless and the wave burn-down could not be used.', 'Nobody owned daily task hygiene during the waves.', 'Give the project officer explicit responsibility for task currency during high-tempo delivery.', 'similar_projects', u('eab4a1e27162'), d(22), 'action_agreed'),
  (u('db43f8501624'), u('bb3bc1733894'), ph(4), null, 'problem', lk('lesson_category', 'Project Management'), 'The supplier''s plan and the university plan were never reconciled', 'Two plans ran in parallel with different task names and dates.', 'Board reporting had to be assembled by hand each fortnight.', 'No agreement at contract stage on a single source of plan truth.', 'Agree a single plan of record with the supplier as a contract schedule.', 'similar_projects', u('60da6bab9ad0'), d(-185), 'identified'),
  (u('fbd1ba5c4aa4'), u('142484a15181'), ph(1), null, 'success', lk('lesson_category', 'Stakeholder Management'), 'Early stakeholder engagement built a strong pilot group', 'Service desk, student services and the students'' union were engaged before the business case was written.', 'The pilot group was full within a week and provided high quality feedback.', 'Engagement started at idea stage rather than at design.', 'Run a stakeholder workshop before the business case for any service-facing change.', 'all_projects', u('53c863c1f96a'), d(-390), 'embedded'),
  (u('84cea71061df'), u('13f8340e52de'), ph(1), null, 'success', lk('lesson_category', 'Stakeholder Management'), 'Faculty engagement before planning shaped the wave order', 'Faculty operations managers were consulted on the deployment order before the plan was drafted.', 'No wave was rescheduled for academic reasons during the rollout.', 'The team invested two weeks in engagement before planning.', 'Consult academic operations before sequencing any estate-wide deployment.', 'similar_projects', u('36e519195168'), d(-622), 'closed'),
  (u('3f00728a9082'), u('1fce5e8639fe'), ph(1), null, 'success', lk('lesson_category', 'Governance'), 'Project board scheduled at initiation for the whole project', 'All six board dates were diarised in the first week, with named deputies.', 'Every decision was taken at the next scheduled board, with no ad hoc escalation.', 'Booking the full sequence up front removed diary friction.', 'Book the full board sequence at initiation, including deputies.', 'all_projects', u('11deba8aff2d'), d(-464), 'embedded'),
  (u('5a268d827168'), u('5a80b922508f'), ph(1), null, 'success', lk('lesson_category', 'Governance'), 'Board dates set for the full lifecycle at mobilisation', 'Boards were booked for twelve months at mobilisation and held even when short.', 'Decision latency averaged four days against a portfolio average of eleven.', 'Regular cadence meant decisions were never waiting for a meeting to be arranged.', 'Book the full board sequence at initiation, including deputies.', 'all_projects', u('3260734c20c8'), d(-304), 'closed'),
  (u('ed9a9cec2839'), u('59cfeef95b28'), ph(3), null, 'success', lk('lesson_category', 'Vendor Management'), 'Good remote collaboration with the supplier', 'Daily fifteen minute calls with the supplier''s engineering lead replaced weekly written reports.', 'Three integration issues were resolved the same day rather than over a fortnight.', 'A short daily rhythm suited a distributed delivery team.', 'Agree a short daily contact rhythm with suppliers on technical delivery, not just weekly reporting.', 'similar_projects', u('157d1593d385'), d(-173), 'closed'),
  (u('bfb19b63f969'), u('bb3bc1733894'), ph(4), null, 'success', lk('lesson_category', 'Vendor Management'), 'Shared defect triage with the implementation partner', 'A joint triage call each morning covered every new defect with both teams present.', 'Defect turnaround fell from six days to two.', 'Joint ownership removed the queue between the two organisations.', 'Run joint defect triage with the supplier from the first day of testing.', 'similar_projects', u('a1cee910a6d1'), d(-13), 'closed'),
  (u('c7271ad96e1f'), u('142484a15181'), ph(2), null, 'success', lk('lesson_category', 'Architecture'), 'Early architecture review avoided a costly integration', 'The review board was consulted during options appraisal rather than at design.', 'A proposed direct database integration was ruled out before any build effort was spent.', 'Consulting architecture at options stage is cheap and changes the answer.', 'Take options to the review board during appraisal, not after a preferred option is chosen.', 'all_projects', u('d3806fe3b1be'), d(-583), 'closed'),
  (u('cbeb8a3726ae'), u('1fce5e8639fe'), ph(4), null, 'success', lk('lesson_category', 'Ways of Working'), 'A two week pilot with lone workers found the real issues', 'A small pilot with estates lone workers ran before the student launch.', 'Four usability issues were fixed before the main launch.', 'Piloting with the most demanding user group first surfaced issues early.', 'Pilot with the most demanding user group, not the easiest.', 'similar_projects', u('403b3213de11'), d(-61), 'closed'),
  (u('5c10bb83f730'), u('13f8340e52de'), ph(5), null, 'success', lk('lesson_category', 'Support & Handover'), 'Support handover ran alongside the first wave', 'The service desk shadowed the deployment team through wave one instead of receiving documentation at the end.', 'First-contact resolution for deployment queries was 78% from wave two onwards.', 'Shadowing transfers knowledge that documentation does not.', 'Build shadowing into the handover approach for any high volume change.', 'all_projects', u('2967ce33d27c'), d(72), 'embedded'),
  (u('ca301e51fe92'), u('59cfeef95b28'), ph(5), null, 'success', lk('lesson_category', 'Communication'), 'A single weekly bulletin replaced ad hoc site emails', 'One bulletin covering all sites replaced per-site emails from three different people.', 'Site queries to the project mailbox fell by two thirds.', 'A single consistent channel reduced confusion.', 'Use one channel and one voice for multi-site communications.', 'similar_projects', u('161d6b100d82'), d(-135), 'closed'),
  (u('07d60d6af300'), u('142484a15181'), ph(2), null, 'problem', lk('lesson_category', 'Governance'), 'The benefits profile was drafted without the benefit owner', 'The profile was written by the project manager and shown to the owner after the business case was approved.', 'Two measures could not be collected and had to be replaced after approval.', 'The gate criterion asked for a profile, not for owner agreement.', 'Require the benefit owner''s sign-off, not just their name, at the business case gate.', 'all_projects', u('eab4a1e27162'), d(-340), 'embedded'),
  (u('9eb5ff711d23'), u('142484a15181'), ph(3), null, 'success', lk('lesson_category', 'Communication'), 'A one-page design summary kept non-technical stakeholders engaged', 'Each design decision was summarised in plain English for the board pack.', 'Board decisions were taken first time without deferral.', 'Plain English summaries let non-specialists engage with technical choices.', 'Produce a one page plain English design summary for every board pack.', 'all_projects', u('60da6bab9ad0'), d(-182), 'closed'),
  (u('301a429344a8'), u('142484a15181'), ph(4), 'Sprint 6', 'problem', lk('lesson_category', 'Training'), 'Service desk training assumed prior knowledge of the platform', 'Training was pitched at the pilot team''s level, not at the wider service desk.', 'Half the analysts needed a second session.', 'Training design skipped a needs analysis.', 'Run a short training needs analysis before designing the sessions.', 'similar_projects', u('53c863c1f96a'), d(-49), 'identified'),
  (u('98c8b58c6660'), u('142484a15181'), ph(4), 'Sprint 7', 'success', lk('lesson_category', 'Ways of Working'), 'Fortnightly show and tell kept the sponsor close', 'A fifteen minute demo each fortnight replaced a written progress report for the sponsor.', 'The sponsor spotted a routing gap early and unblocked it the same day.', 'Showing working software beats describing it.', 'Offer sponsors a short regular demo instead of, not as well as, a written report.', 'all_projects', u('36e519195168'), d(-254), 'closed'),
  (u('7bbb7ceb37a2'), u('142484a15181'), ph(2), null, 'problem', lk('lesson_category', 'Resource Management'), 'The business analyst was shared across three projects', 'The analyst was allocated 20% to this project while carrying two other discovery phases.', 'Requirements took seven weeks against a three week plan.', 'Allocation was agreed at percentages that summed to more than one person.', 'Check the resource dashboard for over-allocation before confirming an allocation.', 'all_projects', u('11deba8aff2d'), d(-461), 'action_agreed'),
  (u('bdd84d03e73e'), u('5a80b922508f'), ph(2), null, 'problem', lk('lesson_category', 'Requirements'), 'Control scope was defined by framework, not by risk', 'The safeguard list was taken wholesale from the framework without filtering by the university''s risk profile.', 'Effort was spent on safeguards with negligible local risk reduction.', 'No risk-based filter was applied at scoping.', 'Filter control frameworks against the local risk register before scoping.', 'similar_projects', u('3260734c20c8'), d(-301), 'action_agreed'),
  (u('dca76b686003'), u('5a80b922508f'), ph(3), null, 'problem', lk('lesson_category', 'Architecture'), 'Monitoring tooling did not cover the research network', 'The tooling was specified against the corporate network only.', 'A separate solution was needed for research, adding £40k.', 'The research network was out of sight during design.', 'Include every network zone in the design scope statement, even those out of scope.', 'similar_projects', u('157d1593d385'), d(-170), 'identified'),
  (u('bc34c353f097'), u('5a80b922508f'), ph(4), null, 'success', lk('lesson_category', 'Testing'), 'Purple team exercise validated the controls in practice', 'A combined attack and defence exercise tested the implemented safeguards.', 'Two misconfigurations were found and fixed before assurance.', 'Practical testing found what document review did not.', 'Run a practical validation exercise before control assurance, not after.', 'similar_projects', u('a1cee910a6d1'), d(-10), 'closed'),
  (u('9f81626fe8bb'), u('5a80b922508f'), ph(3), null, 'problem', lk('lesson_category', 'Communication'), 'Control changes were announced without service context', 'Change notices described the technical control, not the user impact.', 'The service desk received 120 contacts about a change that affected nobody''s daily work.', 'Notices were written by engineers for engineers.', 'Have the service desk review change notices for user impact before they go out.', 'all_projects', u('d3806fe3b1be'), d(-215), 'embedded'),
  (u('1e3a09ee3235'), u('5a80b922508f'), ph(2), null, 'success', lk('lesson_category', 'Stakeholder Management'), 'The insurer was engaged during the business case', 'The broker reviewed the proposed control set before the case was approved.', 'The evidence format was agreed up front and no rework was needed at renewal.', 'Engaging the assuring party early removes late surprises.', 'Engage external assurers during appraisal, not at evidence submission.', 'similar_projects', u('403b3213de11'), d(-423), 'closed'),
  (u('d4401df7ade3'), u('13f8340e52de'), ph(3), null, 'problem', lk('lesson_category', 'Vendor Management'), 'The hardware supplier''s lead times were taken at face value', 'Quoted lead times were used in the plan without a buffer.', 'Two waves were rescheduled when stock slipped.', 'No contingency was applied to supplier-quoted dates.', 'Apply a contingency to supplier-quoted lead times in the baselined plan.', 'all_projects', u('2967ce33d27c'), d(75), 'action_agreed'),
  (u('841970bfab67'), u('13f8340e52de'), ph(2), null, 'success', lk('lesson_category', 'Project Management'), 'A readiness scan before planning made the estimate credible', 'Every device was scanned for compatibility before the plan was written.', 'The hardware replacement estimate was within 2% of actual.', 'Real data beats assumptions for estate-wide work.', 'Complete an estate scan before estimating any device rollout.', 'similar_projects', u('161d6b100d82'), d(-497), 'closed'),
  (u('04e2b496ef43'), u('13f8340e52de'), ph(5), null, 'problem', lk('lesson_category', 'Support & Handover'), 'Deployment documentation was written after handover', 'The support pack was delivered three weeks after the service desk took the service.', 'The desk escalated 60 calls that the pack would have answered.', 'Documentation was scheduled after go-live in the plan.', 'Schedule the support pack to complete before the handover gate, not after it.', 'all_projects', u('eab4a1e27162'), d(28), 'action_agreed'),
  (u('9c75711919f6'), u('13f8340e52de'), ph(6), null, 'success', lk('lesson_category', 'Governance'), 'Closure was run as a working session, not a document review', 'The closure meeting worked through outstanding actions rather than reading a report.', 'Every outstanding action left with an owner and a date.', 'A working session produces commitments; a review produces comments.', 'Run closure as a working session with the owners of every open action present.', 'all_projects', u('60da6bab9ad0'), d(-179), 'closed'),
  (u('490aa5fe9bb5'), u('bb3bc1733894'), ph(2), null, 'problem', lk('lesson_category', 'Governance'), 'The business case overstated benefits with no measurement plan', 'Conversion improvements were claimed without agreeing how they would be measured.', 'At closure only one of four benefits could be evidenced.', 'The case was approved without a measurement plan for each benefit.', 'Require a named measure, data source and owner for each benefit before approval.', 'all_projects', u('53c863c1f96a'), d(-411), 'embedded'),
  (u('9988ce53e677'), u('bb3bc1733894'), ph(3), null, 'problem', lk('lesson_category', 'Architecture'), 'Integration count was underestimated at design', 'Nine integrations were identified at design; fourteen were needed.', 'Build effort exceeded the estimate by 30%.', 'The integration discovery relied on documentation that was out of date.', 'Verify integration inventories against live traffic, not documentation.', 'similar_projects', u('36e519195168'), d(-251), 'action_agreed'),
  (u('177fa89dcc42'), u('bb3bc1733894'), ph(5), null, 'problem', lk('lesson_category', 'Support & Handover'), 'Hypercare ended before the first peak period', 'Early life support ran for four weeks and ended before the first applications peak.', 'The service desk absorbed the peak without supplier support.', 'Hypercare was scoped by duration rather than by business cycle.', 'Scope early life support to cover the first business peak, not a fixed number of weeks.', 'all_projects', u('11deba8aff2d'), d(-93), 'action_agreed'),
  (u('740501c8d5cb'), u('bb3bc1733894'), ph(6), null, 'problem', lk('lesson_category', 'Resource Management'), 'The project team dispersed before closure completed', 'Team members moved to new projects as soon as go-live was achieved.', 'Closure took four months and lessons were captured from memory.', 'No closure allocation was held in the resource plan.', 'Hold a closure allocation for the project manager and business analyst in the resource plan.', 'all_projects', u('3260734c20c8'), d(67), 'identified'),
  (u('ab84c0922c1f'), u('bb3bc1733894'), ph(1), null, 'success', lk('lesson_category', 'Project Management'), 'A short discovery prevented a much larger mistake', 'A six week discovery tested whether the existing platform could be extended before replacement was approved.', 'The replacement case was evidenced rather than assumed.', 'A small investment in discovery de-risked a large investment.', 'Fund a discovery phase for any replacement of a core business system.', 'similar_projects', u('157d1593d385'), d(-532), 'closed'),
  (u('bd504f12e43d'), u('59cfeef95b28'), ph(2), null, 'success', lk('lesson_category', 'Project Management'), 'Phase one lessons were reviewed before phase two planning', 'The phase one lessons log was worked through line by line at mobilisation.', 'Six of the eleven phase one problems did not recur.', 'Reviewing lessons at the start of a follow-on phase is the cheapest improvement available.', 'Review the previous phase''s lessons log at mobilisation of any follow-on phase.', 'all_projects', u('a1cee910a6d1'), d(-372), 'embedded'),
  (u('de87a93c4a4e'), u('59cfeef95b28'), ph(5), null, 'problem', lk('lesson_category', 'Training'), 'Site champions were trained too early', 'Champions were trained eight weeks before their site migrated.', 'Most had forgotten the detail and needed retraining.', 'Training was scheduled for trainer convenience, not for the migration order.', 'Schedule champion training within two weeks of each site''s migration date.', 'similar_projects', u('d3806fe3b1be'), d(-212), 'identified'),
  (u('cdc627e4baab'), u('59cfeef95b28'), ph(6), null, 'problem', lk('lesson_category', 'Governance'), 'Benefits were not handed over at closure', 'The project closed without agreeing who would measure the call cost saving.', 'The saving went unmeasured for two quarters after closure.', 'Closure focused on the delivery position, not the benefits position.', 'Make a completed benefits handover a closure gate criterion.', 'all_projects', u('403b3213de11'), d(-82), 'embedded'),
  (u('1e8ff94fdae9'), u('1fce5e8639fe'), ph(2), null, 'problem', lk('lesson_category', 'Stakeholder Management'), 'The students'' union was consulted after the design was fixed', 'Consultation happened at the point of launch planning.', 'Two privacy concerns had to be addressed with configuration changes post-launch.', 'The union was treated as a communications audience rather than a stakeholder.', 'Treat representative bodies as stakeholders in design, not recipients of communications.', 'similar_projects', u('2967ce33d27c'), d(-287), 'action_agreed'),
  (u('34d743d29cbd'), u('1fce5e8639fe'), ph(3), null, 'success', lk('lesson_category', 'Procurement'), 'A framework call-off avoided a full tender', 'An existing framework was used rather than running a new procurement.', 'Contracting took three weeks rather than four months.', 'Checking frameworks first is quick and often sufficient.', 'Check existing frameworks before planning any new procurement.', 'all_projects', u('161d6b100d82'), d(-129), 'closed'),
  (u('4839da0f08e5'), u('1fce5e8639fe'), ph(6), null, 'success', lk('lesson_category', 'Ways of Working'), 'A one page closure note suited a small project', 'Closure used the lightweight note rather than the full report.', 'Closure completed in two weeks with no loss of assurance.', 'Right-sized governance keeps small projects moving.', 'Use the tier-appropriate closure route rather than defaulting to the full report.', 'all_projects', u('eab4a1e27162'), d(31), 'closed'),
  (u('fd380107a19a'), u('1fce5e8639fe'), ph(4), null, 'problem', lk('lesson_category', 'Testing'), 'Accessibility testing was not planned for the mobile app', 'Accessibility testing was assumed to be covered by the supplier.', 'Two screen reader defects were found by a student after launch.', 'Supplier test coverage was never confirmed in writing.', 'Confirm in writing what the supplier tests, and test the rest yourself.', 'all_projects', u('60da6bab9ad0'), d(-203), 'action_agreed'),
  (u('66878591f341'), u('142484a15181'), ph(1), null, 'problem', lk('lesson_category', 'Communication'), 'The project name meant nothing to stakeholders', 'Early communications used the product name with no explanation.', 'Stakeholders did not recognise the project in portfolio reporting and missed two consultations.', 'The product name was adopted as the project name without a plain description.', 'Pair a product name with a plain English description in every external communication.', 'all_projects', u('53c863c1f96a'), d(-408), 'closed'),
  (u('3a765e641002'), u('5a80b922508f'), ph(5), null, 'problem', lk('lesson_category', 'Change Management & Adoption'), 'Multi-factor prompts increased without warning users', 'A control change increased authentication prompts with no user notice.', 'Service desk contacts rose 180% for a week.', 'The change was assessed for technical risk but not for user impact.', 'Add a user impact assessment to every control change request.', 'all_projects', u('36e519195168'), d(-248), 'action_agreed'),
  (u('c99e83079705'), u('13f8340e52de'), ph(4), null, 'problem', lk('lesson_category', 'Resource Management'), 'Deployment engineers were double-booked with BAU', 'Engineers were allocated at 60% but carried a full BAU rota.', 'Two waves ran at half the planned rate.', 'BAU commitment was not deducted from available capacity.', 'Use the resource dashboard''s BAU percentage when planning delivery capacity.', 'all_projects', u('11deba8aff2d'), d(-90), 'embedded'),
  (u('7c09e55d5456'), u('bb3bc1733894'), ph(2), null, 'problem', lk('lesson_category', 'Procurement'), 'Evaluation criteria did not include implementation capability', 'Selection weighted product function heavily and implementation capability lightly.', 'The chosen partner''s first team was inexperienced and was replaced after eight weeks.', 'The evaluation model was copied from a product-only purchase.', 'Weight implementation capability separately when buying product plus implementation.', 'similar_projects', u('3260734c20c8'), d(-322), 'identified'),
  (u('95e1bf839ba8'), u('59cfeef95b28'), ph(3), null, 'problem', lk('lesson_category', 'Ways of Working'), 'Two teams used different definitions of done for a migrated site', 'Networks and telephony had different completion criteria.', 'Four sites were reported complete twice and then reopened.', 'No shared definition of done was agreed at mobilisation.', 'Agree a written definition of done for shared deliverables at mobilisation.', 'all_projects', u('157d1593d385'), d(-164), 'action_agreed'),
  (u('c88bf7cf31c6'), u('1fce5e8639fe'), ph(5), null, 'problem', lk('lesson_category', 'Support & Handover'), 'The service desk had no test account for the app', 'Analysts could not reproduce user reports because they had no account.', 'First-contact resolution was 22% in the first month.', 'Support enablement was not part of the handover checklist.', 'Give the service desk working test accounts before handover, not after.', 'all_projects', u('a1cee910a6d1'), d(-4), 'embedded'),
  (u('f6b33c0e436a'), u('bb3bc1733894'), ph(5), null, 'success', lk('lesson_category', 'Training'), 'Recorded micro-training replaced classroom sessions', 'Five minute recordings per task replaced two hour classroom sessions.', 'Completion rates went from 45% to 91%.', 'Short task-based training fits how people actually work.', 'Default to short task-based recordings for system training.', 'all_projects', u('d3806fe3b1be'), d(-209), 'embedded'),
  (u('223292c62b90'), u('59cfeef95b28'), ph(4), null, 'success', lk('lesson_category', 'Testing'), 'A pilot site proved the migration runbook', 'One small site was migrated first purely to test the runbook.', 'Eleven runbook corrections were made before the main waves.', 'Testing the process, not just the technology, prevented repeated errors.', 'Migrate one low-risk site first to prove the runbook.', 'similar_projects', u('403b3213de11'), d(-79), 'closed'),
  (u('475640e7edd0'), u('5a80b922508f'), ph(6), null, 'problem', lk('lesson_category', 'Project Management'), 'Lessons were captured only at closure', 'No phase reviews were held; everything was captured in one closure session.', 'Early phase lessons were forgotten and the same scoping problem recurred at phase four.', 'Phase lessons reviews were not scheduled.', 'Hold a short lessons review at every phase gate rather than one session at closure.', 'all_projects', u('2967ce33d27c'), d(81), 'embedded');
